package com.securevault.service;
import com.securevault.entity.User;import org.springframework.stereotype.Service;import java.net.URI;import java.net.http.*;
@Service public class PushNotificationService{public void send(User user,String title,String message){String endpoint=System.getenv("SECUREVAULT_PUSH_ENDPOINT");String token=System.getenv("SECUREVAULT_PUSH_TOKEN");if(endpoint==null||endpoint.isBlank()||token==null||token.isBlank())return;try{String json="{\"to\":\""+user.getEmail().replace("\"","\\\"")+"\",\"title\":\""+title.replace("\"","\\\"")+"\",\"message\":\""+message.replace("\"","\\\"")+"\"}";HttpRequest r=HttpRequest.newBuilder(URI.create(endpoint)).header("Authorization","Bearer "+token).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(json)).build();HttpClient.newHttpClient().sendAsync(r,HttpResponse.BodyHandlers.discarding());}catch(Exception ignored){}}}
